import{_ as a,b as o,c as r,I as e}from"./chunks/framework.C6cPs9Ia.js";const n="/LQY/images/portrait.jpg",g=JSON.parse('{"title":"关于本站","description":"关于柳卿烟和这个猫窝的一切——一个猫羽雫单推人的二次元高中生","frontmatter":{"title":"关于本站","date":"2026-09-16T00:00:00.000Z","tags":["关于"],"head":[["meta",{"name":"description","content":"关于柳卿烟和这个猫窝的一切——一个猫羽雫单推人的二次元高中生"}],["meta",{"name":"keywords","content":"关于, 柳卿烟, 猫羽雫, 二次元, 高中生"}]]},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),i={name:"about.md"};function s(l,t,d,p,u,c){return o(),r("div",null,[...t[0]||(t[0]=[e('<p><img src="'+n+'" alt="" data-fancybox="gallery"></p><h2 id="你好-这里是柳卿烟" tabindex="-1">你好，这里是柳卿烟 <a class="header-anchor" href="#你好-这里是柳卿烟" aria-label="Permalink to &quot;你好，这里是柳卿烟&quot;">​</a></h2><p>一名普通的（自称）高中二年级学生，坐标某个夏天很热、冬天很冷的城市。</p><p>白天，课表上的数学、物理、英语轮番轰炸；放学后，书包一甩就切换到另一个世界——那里有单推的猫耳少女、今晚要漂移的赛道、每周更新的新番，还有 4399 时代的考古现场。</p><p><strong>概括一下的话：在题海和二次元之间反复横跳，两边都不想放弃，两边都舍不得。</strong></p><h2 id="兴趣图鉴" tabindex="-1">兴趣图鉴 <a class="header-anchor" href="#兴趣图鉴" aria-label="Permalink to &quot;兴趣图鉴&quot;">​</a></h2><ul><li>🐾 <strong>猫羽雫单推人</strong>：蓝发猫耳、149cm、虎牙傲娇——我的本命，不服不辩（可以评论区辩，输了我也不会改）</li><li>📺 <strong>追番</strong>：每季 3-5 部起步，三集定生死的扫雷流，扫雷报告发在站里</li><li>🚗 <strong>QQ飞车</strong>：钻石星耀反复横跳的普通车手，周五晚固定开黑</li><li>🕹️ <strong>网页游戏考古</strong>：洛克王国、赛尔号、摩尔庄园、4399 万神殿……我是带着皮尺来的</li><li>🎧 <strong>歌单洁癖</strong>：通学路的 23 分钟必须配对味的 BGM</li><li>💻 <strong>瞎折腾</strong>：HTML/CSS/JS/Python 三脚猫，最大的成就是这个猫窝本身</li></ul><h2 id="本站简史" tabindex="-1">本站简史 <a class="header-anchor" href="#本站简史" aria-label="Permalink to &quot;本站简史&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时期</th><th>形态</th></tr></thead><tbody><tr><td>一代目</td><td>手写静态页，纯 HTML+CSS，丑但真诚</td></tr><tr><td>二代目</td><td>Astro + Mizuki 主题，粉色的温柔</td></tr><tr><td>三代目</td><td>VitePress + 猫窝主题，现在这个样子（蓝色 + 猫爪 + Live2D）</td></tr></tbody></table><p>域名用的是 GitHub Pages（<code>liu-qinyan.github.io/LQY</code>），托管在 GitHub 上，全部源码也在同一个仓库里。看板娘、猫爪特效、8-bit 背景音乐都是自己动手改的，欢迎右键审查（笑）。</p><h2 id="一些问答" tabindex="-1">一些问答 <a class="header-anchor" href="#一些问答" aria-label="Permalink to &quot;一些问答&quot;">​</a></h2><p><strong>Q：为什么主题是猫？</strong> A：因为本命是猫羽雫。她蓝发蓝瞳、爱吃爱睡爱玩、还有点小傲娇——这只猫窝的一切配色和氛围，都是照着那个方向搭的。</p><p><strong>Q：为什么不玩手游了？</strong> A：玩过，后来发现自己更喜欢&quot;上车就能跑一圈&quot;和&quot;打开网页就能挖金矿&quot;的纯粹快乐。抽卡的钱改投了猫咖基金和谷子。</p><p><strong>Q：更新的动力是？</strong> A：评论区的每一条留言，和&quot;又活过了一场月考&quot;的仪式感。</p><p><strong>Q：可以转载文章吗？</strong> A：可以，注明作者和原文地址即可。商业用途不行，虽然也不知道这种高中生日记有什么好商用的（笑）。</p><p><strong>Q：怎么联系？</strong> A：评论区留言最快；也可以在 <a href="https://github.com/liu-qinyan" target="_blank" rel="noreferrer">GitHub</a> 提 issue。</p><h2 id="给同路人的话" tabindex="-1">给同路人的话 <a class="header-anchor" href="#给同路人的话" aria-label="Permalink to &quot;给同路人的话&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>如果屏幕前的你也是&quot;白天题海、晚上二次元&quot;的同款高中生—— 平衡好学习和热爱，两边的快乐都别放弃。 月考周会断更，但猫窝永远都在，放学后见。</p></div>',18)])])}const b=a(i,[["render",s]]);export{g as __pageData,b as default};
